{"description":"Connect via telnet and capture console output","cmd":"cat > /tmp/telnet_capture.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 15
spawn telnet 127.0.0.1 6665
log_user 1
set out [open /tmp/telnet_capture.out w]
while {1} {
    set got [expect {
        -re {login:} { puts $out "LOGIN_PROMPT_SEEN"; break }
        timeout { puts $out "TIMEOUT"; break }
        eof { puts $out "EOF"; break }
    }]
}
close $out
send_user "\n(capture finished)\n"
EOF
expect /tmp/telnet_capture.exp > /tmp/expect_console.log 2>&1 &
EXPECTPID=$!; sleep 18; kill $EXPECTPID 2>/dev/null; wait $EXPECTPID 2>/dev/null; echo "--- capture file ---"; cat /tmp/telnet_capture.out 2>/dev/null; echo "--- expect console log (last 60 lines) ---"; tail -60 /tmp/expect_console.log","yield_time_ms":22000}

{"description":"Test raw tcp serial with python client connected longer","cmd":"rm -f /tmp/pycap.bin /tmp/pycap.log; qemu-system-x86_64 -m 256 -display none -serial tcp:127.0.0.1:6668,server,nowait -kernel /tmp/vmlinuz-lts -append 'console=ttyS0' -no-reboot > /tmp/qraw2.log 2>&1 & QPID=$!; sleep 2; cat > /tmp/pycap.py <<'EOF'
import socket, time, sys
s = socket.create_connection(('127.0.0.1', 6668), timeout=30)
s.settimeout(1.0)
t0 = time.time()
data = b''
try:
    while time.time() - t0 < 25:
        try:
            chunk = s.recv(65536)
        except socket.timeout:
            continue
        if not chunk:
            print("closed at", round(time.time()-t0,1)); break
        data += chunk
        if b'Kernel panic' in data or b'login:' in data:
            print("matched at", round(time.time()-t0,1)); break
except Exception as e:
    print("err", e)
print("total bytes", len(data), "elapsed", round(time.time()-t0,1))
open('/tmp/pycap.bin','wb').write(data)
EOF
python3 /tmp/pycap.py 2>&1 | tee /tmp/pycap.log; kill $QPID 2>/dev/null; echo "--- captured first 40 lines ---"; cat /tmp/pycap.bin | tr -d '\0' | head -40","yield_time_ms":30000}

{"description":"Connect to running full alpine telnet and send input","cmd":"cat > /tmp/t.nc <<'EOF'
