{"description":"Verify port 6665 listening and create poller script","cmd":"awk 'NR>1 && $4=="0A" {print $2}' /proc/net/tcp | grep -i ':1a09' && echo "6665 LISTENING"; cat > /tmp/poll.exp <<'EOF'
#!/usr/bin/expect -f
set log [open "/tmp/alpine_ready.log" w]
set timeout 15
spawn telnet 127.0.0.1 6665
set attempts 0
while 1 {
    incr attempts
    expect {
        -re {login: *} {
            puts $log "READY attempts=$attempts [clock format [clock seconds]]"
            flush $log
            close $log
            send_user "READY\n"
            exit 0
        }
        timeout {
            puts $log "attempt=$attempts no-prompt-yet [clock seconds]"
            flush $log
        }
        eof {
            puts $log "EOF at attempt=$attempts"
            flush $log
            close $log
            exit 1
        }
    }
}
EOF
chmod +x /tmp/poll.exp; echo "poller script written""}

